/* styles.css — 文枢 StructDoc */

:root {
  --bg: #f2f4f8;
  --panel: #ffffff;
  --line: #e3e7ee;
  --line-strong: #ccd4de;
  --ink: #1b2430;
  --muted: #67717f;
  --faint: #98a2b0;
  --accent: #2f5fe0;
  --accent-weak: #e8eefc;
  --warn: #9a5b00;
  --warn-bg: #fdf3e0;
  --warn-line: #eed7a4;
  --ok: #1a7f3c;
  --ok-bg: #e9f7ee;
  --ok-line: #cdeeda;
  --danger: #c0392b;
  --shadow: 0 8px 28px rgba(15, 23, 42, .14);
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 14px/1.6 "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  display: flex;
  flex-direction: column;
}
.hidden { display: none !important; }
button { font: inherit; color: inherit; }

/* ---------- 顶栏 ---------- */
.topbar {
  display: flex; align-items: center; gap: 12px;
  padding: 8px 14px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.brand { display: flex; align-items: baseline; gap: 8px; white-space: nowrap; }
.brand .logo { font-weight: 800; font-size: 17px; color: var(--accent); letter-spacing: .04em; }
.brand-sub { font-size: 11px; color: var(--faint); letter-spacing: .05em; }
.doc-title {
  flex: 1 1 200px; min-width: 150px;
  font-size: 15px; font-weight: 600; color: var(--ink);
  border: 1px solid transparent; background: transparent;
  border-radius: 8px; padding: 6px 10px;
}
.doc-title:hover { border-color: var(--line); }
.doc-title:focus { outline: none; border-color: var(--accent); background: #fff; }
.stats { font-size: 12px; color: var(--muted); white-space: nowrap; }
.sync {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12px; padding: 3px 10px; border-radius: 999px;
  border: 1px solid var(--line); white-space: nowrap;
}
.sync.ok { color: var(--ok); background: var(--ok-bg); border-color: var(--ok-line); }
.sync.editing { color: var(--warn); background: var(--warn-bg); border-color: var(--warn-line); }
.sync svg { flex: none; }
.actions { display: flex; align-items: center; gap: 6px; }
.count { font-size: 11px; color: var(--faint); }

.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 10px; border: 1px solid var(--line);
  background: #fff; border-radius: 8px; cursor: pointer;
  font-size: 13px; color: #333e4e;
}
.btn:hover:not(:disabled) { border-color: var(--line-strong); background: #f7f9fc; }
.btn:disabled { opacity: .4; cursor: default; }
.btn-icon { padding: 5px 7px; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn.primary:hover:not(:disabled) { background: #2853c4; }
.btn.danger:hover:not(:disabled) { color: var(--danger); border-color: var(--danger); }
.btn.mini { padding: 1px 8px; font-size: 12px; border-radius: 6px; }

/* ---------- 三栏布局 ---------- */
main {
  flex: 1; min-height: 0;
  display: grid;
  grid-template-columns: 236px minmax(400px, 1fr) minmax(400px, 1fr);
}
.outline-col, .editor-col, .preview-col { min-height: 0; overflow: auto; }
.outline-col { background: var(--panel); border-right: 1px solid var(--line); display: flex; flex-direction: column; }
.preview-col { background: #fbfcfe; border-left: 1px solid var(--line); }
.col-head {
  position: sticky; top: 0; z-index: 5;
  background: inherit; padding: 9px 14px;
  font-size: 12px; color: var(--muted);
  border-bottom: 1px solid var(--line);
  display: flex; justify-content: space-between; align-items: center; gap: 8px;
}
.col-hint { font-size: 11px; color: var(--faint); font-weight: 400; }

/* ---------- 大纲 ---------- */
.outline-list { padding: 8px; }
.outline-item {
  display: flex; width: 100%; text-align: left; align-items: center; gap: 6px;
  border: 0; background: none; padding: 5px 8px; border-radius: 7px;
  cursor: pointer; color: var(--ink); font-size: 13px; line-height: 1.45;
}
.outline-item:hover { background: var(--accent-weak); }
.outline-item .outline-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.outline-item.lv1 { font-weight: 700; }
.outline-item.lv2 { padding-left: 24px; }
.outline-item.lv3 { padding-left: 40px; font-size: 12.5px; color: #3c4656; }
.o-warn {
  flex: none; width: 15px; height: 15px; border-radius: 50%;
  background: var(--warn); color: #fff; font-size: 11px;
  line-height: 15px; text-align: center;
}
.outline-empty { padding: 14px; color: var(--faint); font-size: 12.5px; }
.outline-meta {
  margin-top: auto; padding: 10px 14px;
  border-top: 1px solid var(--line);
  font-size: 12px; color: var(--faint);
}

/* ---------- 编辑器 ---------- */
.editor-inner { max-width: 680px; margin: 0 auto; padding: 4px 24px 70px; }
.editor-list { padding-top: 4px; }
.empty-state { margin: 90px auto 0; text-align: center; color: var(--muted); }

.block {
  position: relative;
  border: 1px solid transparent; border-radius: 10px;
  padding: 1px 8px 3px 6px; margin: 2px 0;
}
.block:hover { border-color: var(--line); background: #fff; }
.block.flash { animation: flash 1.1s ease; }
@keyframes flash {
  0% { box-shadow: 0 0 0 3px var(--accent-weak); border-color: var(--accent); }
  100% { box-shadow: 0 0 0 0 transparent; }
}
.rail { display: flex; align-items: center; gap: 2px; padding: 2px 0; opacity: .9; }
.rail .btn { padding: 2px 5px; border-color: transparent; background: transparent; border-radius: 6px; color: var(--muted); }
.rail .btn:hover:not(:disabled) { background: var(--accent-weak); color: var(--accent); border-color: transparent; }
.rail .btn:disabled { opacity: .25; }
.rail .btn svg { display: block; }
.chip {
  font-size: 11px; font-weight: 600; letter-spacing: .03em;
  color: var(--accent); background: var(--accent-weak);
  border-radius: 5px; padding: 1px 6px; min-width: 36px; text-align: center;
}
.chip-h { color: #7c3aed; background: #f1eafd; }
.chip-li { color: #0e7490; background: #dff4fa; }
.chip-quote { color: #a16207; background: #fbf0d3; }
.chip-code { color: #334155; background: #e8edf3; }
.chip-hr { color: var(--faint); background: #eef1f5; }

.text-wrap { display: flex; align-items: flex-start; gap: 2px; }
.text-wrap.indent-1 { padding-left: 24px; }
.text-wrap.indent-2 { padding-left: 48px; }
.text-wrap.indent-3 { padding-left: 72px; }
.li-marker {
  flex: none; width: 24px; text-align: right; padding-right: 7px;
  color: var(--muted); font-size: 14px; line-height: 1.65; padding-top: 6px;
}
.block-input {
  flex: 1; width: 100%;
  border: 0; background: transparent; resize: none;
  padding: 6px 4px; color: var(--ink);
  font: inherit; line-height: 1.65;
}
.block-input:focus { outline: none; }
.input-h1 { font-size: 24px; font-weight: 700; line-height: 1.4; }
.input-h2 { font-size: 19px; font-weight: 700; line-height: 1.45; }
.input-h3 { font-size: 16px; font-weight: 600; }
.input-quote {
  border-left: 3px solid var(--warn-line); background: #fffdf5;
  padding-left: 10px; color: #5b5342;
}
.input-code {
  font-family: Consolas, "Courier New", monospace;
  font-size: 13px; line-height: 1.55;
  background: #f6f8fa; border: 1px solid var(--line); border-radius: 8px;
  padding: 8px 10px;
}
.block.b-code { padding-top: 3px; }
.hr-line { border-top: 2px solid var(--line-strong); margin: 9px 4px 7px; }

/* ---------- 结构检查条 ---------- */
.issue-strip {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  margin: 10px 0 6px; padding: 8px 12px;
  border-radius: 10px; font-size: 12.5px;
}
.issue-strip.warn { background: var(--warn-bg); border: 1px solid var(--warn-line); color: var(--warn); }
.issue-strip.ok { background: var(--ok-bg); border: 1px solid var(--ok-line); color: var(--ok); }
.issue-title { font-weight: 700; }
.issue-chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: #fff; border: 1px solid var(--warn-line); border-radius: 999px;
  padding: 2px 6px 2px 10px; color: #7a5200; cursor: pointer;
}

/* ---------- 预览 ---------- */
.preview-body { max-width: 660px; margin: 0 auto; padding: 24px 30px 90px; }
.pv-title { font-size: 26px; font-weight: 800; line-height: 1.35; margin: 2px 0 4px; }
.pv-rule { border: 0; border-top: 1px solid var(--line); margin: 10px 0 4px; }
.preview-body h1, .preview-body h2, .preview-body h3 { line-height: 1.4; margin: 1.15em 0 .4em; }
.preview-body h1 { font-size: 21px; }
.preview-body h2 { font-size: 18px; }
.preview-body h3 { font-size: 15.5px; }
.preview-body p { margin: .5em 0; white-space: pre-wrap; }
.preview-body ul, .preview-body ol { margin: .45em 0; padding-left: 26px; }
.preview-body li { margin: .22em 0; }
.preview-body ul, .preview-body ol { }
.preview-body blockquote {
  margin: .8em 0; padding: 8px 14px;
  border-left: 3px solid #e5c26b; background: #fffaf0;
  color: #6b5a33; border-radius: 0 8px 8px 0; white-space: pre-wrap;
}
.preview-body pre {
  background: #f3f5f9; border: 1px solid var(--line); border-radius: 8px;
  padding: 12px 14px; overflow: auto;
  font-size: 12.5px; line-height: 1.55;
}
.preview-body pre code { font-family: Consolas, "Courier New", monospace; }
.preview-body hr { border: 0; border-top: 2px solid var(--line-strong); margin: 1.3em 0; }

/* ---------- 浮层 ---------- */
.menu {
  position: fixed; z-index: 1000;
  background: #fff; border: 1px solid var(--line); border-radius: 10px;
  box-shadow: var(--shadow); padding: 5px;
  min-width: 172px; max-height: 70vh; overflow: auto;
}
.menu-item {
  display: flex; align-items: center; gap: 8px;
  width: 100%; text-align: left;
  border: 0; background: none; padding: 7px 10px; border-radius: 7px;
  cursor: pointer; font-size: 13px;
}
.menu-item:hover:not(:disabled) { background: var(--accent-weak); color: var(--accent); }
.menu-item.current { color: var(--faint); }
.menu-item.current:hover { background: none; color: var(--faint); cursor: default; }
.menu-item:disabled { color: var(--faint); cursor: default; }

.modal {
  position: fixed; inset: 0; z-index: 1100;
  background: rgba(15, 23, 42, .42);
  display: flex; align-items: center; justify-content: center; padding: 20px;
}
.modal-card {
  background: #fff; border-radius: 14px; box-shadow: var(--shadow);
  width: min(680px, 100%); max-height: 86vh;
  display: flex; flex-direction: column;
}
.modal-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px 0; }
.modal-head h3 { margin: 0; font-size: 16px; }
.modal-hint { margin: 6px 18px 0; font-size: 12.5px; color: var(--muted); }
.modal-text {
  margin: 12px 18px; height: 300px; resize: vertical;
  border: 1px solid var(--line); border-radius: 10px; padding: 12px;
  font-family: Consolas, "Courier New", monospace;
  font-size: 12.5px; line-height: 1.55; color: var(--ink);
}
.modal-text:focus { outline: none; border-color: var(--accent); }
.modal-foot { display: flex; justify-content: flex-end; gap: 8px; padding: 0 18px 16px; }

.toast {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%);
  background: #1e2836; color: #fff;
  padding: 8px 16px; border-radius: 999px; font-size: 13px;
  z-index: 1200; box-shadow: var(--shadow);
}

/* ---------- 窄屏 ---------- */
@media (max-width: 1100px) {
  main { grid-template-columns: 1fr; }
  .outline-col { display: none; }
  .preview-col { border-left: 0; border-top: 1px solid var(--line); }
}

